import sqlite3
import json
import os
from datetime import datetime

DB_PATH = os.path.join(os.path.dirname(__file__), "..", "hub.db")

def init_db():
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    
    # Table for storing final alerts generated by the Hub
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS alerts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            timestamp TEXT,
            category TEXT,
            message TEXT,
            status TEXT DEFAULT 'UNREAD'
        )
    ''')
    
    # Table for storing agent configurations (so user can tweak via UI)
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS agent_config (
            agent_name TEXT PRIMARY KEY,
            model TEXT,
            role TEXT,
            goal TEXT,
            backstory TEXT,
            cron_schedule TEXT
        )
    ''')
    
    # Table for user's watchlist
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS stock_watchlist (
            ticker TEXT PRIMARY KEY,
            added_date TEXT
        )
    ''')
    
    # Table for system optimizations
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS optimizations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            timestamp TEXT,
            project TEXT,
            suggestion TEXT
        )
    ''')
    
    # Insert default configurations if they don't exist
    default_configs = [
        ("StockAgent", "deepseek/deepseek-chat", "Quant Trading Engineer", "Run SMC filters on the Watchlist. Assign a 0-100 Build-Up Score to EVERY ticker based on its technical setup, even if there is no entry signal. Output explicit Long/Short setups with Entry/Stop/Target levels if the score is > 85.", "You are an elite quantitative algorithm.", "0 * * * *"),
        ("FlightAgent", "deepseek/deepseek-chat", "Vacation Deal Finder", "Find incredibly cheap round-trip flights from Tel Aviv (TLV) to Europe for 1 adult. You must use the scraper to get real prices.", "You are a frugal Israeli travel expert. You never hallucinate prices. You always rely on the scraper tool.", "0 */12 * * *"),
        ("ChiefIntelligenceOfficer", "deepseek/deepseek-chat", "Manager", "Verify sub-agent data.", "You are the smart manager.", "N/A"),
        ("OptimizationAgent", "deepseek/deepseek-chat", "Systems Architect", "Review the final output of sweeps to suggest efficiency, accuracy, or cost optimizations.", "You are a passive AI optimization architect. You read agent logs and suggest systemic improvements.", "N/A")
    ]
    
    for config in default_configs:
        cursor.execute('''
            INSERT OR IGNORE INTO agent_config (agent_name, model, role, goal, backstory, cron_schedule)
            VALUES (?, ?, ?, ?, ?, ?)
        ''', config)
        
    conn.commit()
    conn.close()

def log_alert(category, message):
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute('''
        INSERT INTO alerts (timestamp, category, message)
        VALUES (?, ?, ?)
    ''', (datetime.now().isoformat(), category, message))
    conn.commit()
    conn.close()

def get_alerts(category=None):
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    if category:
        cursor.execute('SELECT timestamp, category, message, status FROM alerts WHERE category = ? ORDER BY id DESC LIMIT 50', (category,))
    else:
        cursor.execute('SELECT timestamp, category, message, status FROM alerts ORDER BY id DESC LIMIT 50')
    results = cursor.fetchall()
    conn.close()
    return results

def get_agent_config(agent_name):
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute('SELECT model, role, goal, backstory, cron_schedule FROM agent_config WHERE agent_name = ?', (agent_name,))
    result = cursor.fetchone()
    conn.close()
    return result

def get_watchlist():
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute('SELECT ticker FROM stock_watchlist')
    results = [row[0] for row in cursor.fetchall()]
    conn.close()
    return results

if __name__ == "__main__":
    init_db()
    print("Database initialized successfully.")

def log_optimization(project, suggestion):
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute('INSERT INTO optimizations (timestamp, project, suggestion) VALUES (?, ?, ?)', (datetime.now().isoformat(), project, suggestion))
    conn.commit()
    conn.close()

def get_optimizations():
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute('SELECT timestamp, project, suggestion FROM optimizations ORDER BY id DESC LIMIT 50')
    results = cursor.fetchall()
    conn.close()
    return results

def get_agent_feedback(agent_name, limit=3):
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute('CREATE TABLE IF NOT EXISTS feedback_memory (id INTEGER PRIMARY KEY AUTOINCREMENT, agent_name TEXT, feedback TEXT, timestamp TEXT)')
    cursor.execute('SELECT feedback FROM feedback_memory WHERE agent_name = ? ORDER BY id DESC LIMIT ?', (agent_name, limit))
    results = [row[0] for row in cursor.fetchall()]
    conn.close()
    return results
